/// <summary>
/// The codec between a population entry's native words and the typed spawn settings its species reads (#1471, #1472):
/// the initialization word, the species bits of the property word, the extra-property word a few species author
/// settings in, and the two parameter words. This type is the one place that knows each species' packing, for the
/// checks that compare the compiled populations with native records and the fixtures that author entries as words.
/// Generated by the #1472 population generator.
/// </summary>
[EncodingOwner("population entry initialization, species property bits, extra-property settings and parameter words")]
internal static class EnemySpawnSettingsCodec
{
    /// <summary>The settings the words give an <paramref name="enemy"/>; a species its entry tells nothing gets <see cref="EnemySpawnSettings.None"/>.</summary>
    /// <exception cref="InvalidDataException">A word holds a setting the species cannot start with.</exception>
    public static EnemySpawnSettings Decode(EnemyDefinitionId enemy, PopulationWords words) => enemy switch
    {
        EnemyDefinitionId.CeresDoor => new CeresDoorSpawnSettings(Variant: Bits(words.Parameter1, 0, 16) switch { 0 => CeresDoorVariant.NormalFacingRight, 1 => CeresDoorVariant.NormalFacingLeft, 2 => CeresDoorVariant.RotatingElevatorPreExplosionOverlay, 3 => CeresDoorVariant.RidleyRoomFacingRight, 4 => CeresDoorVariant.RotatingElevatorInvisibleWall, 5 => CeresDoorVariant.RidleyEscapeFloorLeftWall, 6 => CeresDoorVariant.RidleyEscapeFloorRightWall, var other => throw Unmapped("Variant", other) }),
        EnemyDefinitionId.Steam => new CeresSteamSpawnSettings(Variant: Bits(words.Parameter1, 0, 16) switch { 0 => CeresSteamVariant.Up, 1 => CeresSteamVariant.Left, 2 => CeresSteamVariant.Down, 3 => CeresSteamVariant.Right, 4 => CeresSteamVariant.RotatingElevatorLeft, 5 => CeresSteamVariant.RotatingElevatorRight, var other => throw Unmapped("Variant", other) }),
        EnemyDefinitionId.TourianStatue => new TourianEntranceStatueSpawnSettings(Statue: Bits(words.Parameter1, 0, 16) switch { 0 => TourianEntranceStatueProgram.BaseDecoration, 2 => TourianEntranceStatueProgram.Ridley, 4 => TourianEntranceStatueProgram.Phantoon, var other => throw Unmapped("Statue", other) }),
        EnemyDefinitionId.MotherBrainTubes => new MotherBrainTubeSpawnSettings(Piece: Bits(words.Parameter1, 1, 15) switch { 0 => MotherBrainTubePiece.BottomLeft, 1 => MotherBrainTubePiece.BottomRight, 2 => MotherBrainTubePiece.BottomMiddleLeft, 3 => MotherBrainTubePiece.BottomMiddleRight, 4 => MotherBrainTubePiece.Main, var other => throw Unmapped("Piece", other) }, FallDelay: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Rinka => new RinkaSpawnSettings(Special: (words.Parameter1 & 65535) != 0),
        EnemyDefinitionId.Zebetite => new ZebetiteSpawnSettings(Half: Bits(words.Parameter1, 0, 16) switch { 0 => ZebetiteHalf.Primary, _ => ZebetiteHalf.Linked }),
        EnemyDefinitionId.RidleyExplosion => new RidleyExplosionSpawnSettings(Part: Bits(words.Parameter1, 0, 16) switch { 0 => RidleyExplosionPart.Tail0, 2 => RidleyExplosionPart.Tail1, 4 => RidleyExplosionPart.Tail2, 6 => RidleyExplosionPart.Tail3, 8 => RidleyExplosionPart.Tail4, 10 => RidleyExplosionPart.Tail5, 12 => RidleyExplosionPart.TailTip, 14 => RidleyExplosionPart.Wings, 16 => RidleyExplosionPart.Legs, 18 => RidleyExplosionPart.OpenHeadAndNeck, 20 => RidleyExplosionPart.Torso, 22 => RidleyExplosionPart.Claw, var other => throw Unmapped("Part", other) }),
        EnemyDefinitionId.Dachora => new DachoraSpawnSettings(Facing: Bits(words.Parameter1, 0, 1) switch { 0 => HorizontalDirection.Left, 1 => HorizontalDirection.Right, var other => throw Unmapped("Facing", other) }, Echo: (words.Parameter1 & 32768) != 0),
        EnemyDefinitionId.EtecoonEscape => new EscapeEtecoonSpawnSettings(Role: Bits(words.Parameter1, 1, 15) switch { 0 => EscapeEtecoonRole.LeftWalker, 1 => EscapeEtecoonRole.RightWalker, 2 => EscapeEtecoonRole.WaitForEscapeEvent, var other => throw Unmapped("Role", other) }),
        EnemyDefinitionId.Etecoon => new EtecoonSpawnSettings(Heading: Bits(words.Parameter1, 0, 8) switch { 0 => HorizontalDirection.Left, _ => HorizontalDirection.Right }, TeachingHops: Bits(words.Parameter1, 8, 8), Route: Bits(words.Parameter2, 0, 8), QuakePauseFrames: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Atomic => new AtomicSpawnSettings(Spin: Bits(words.Parameter1, 0, 16), SpeedIndex: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Boulder => new BoulderSpawnSettings(TriggerHeight: Bits(words.Initialization, 0, 8), TriggerReach: Bits(words.Parameter2, 0, 8), Drop: Bits(words.Parameter2, 8, 8), Roll: Bits(words.Parameter1, 8, 8) switch { 0 => BoulderRoll.Right, 1 => BoulderRoll.Left, 2 => BoulderRoll.LeftBreakingOnImpact, var other => throw Unmapped("Roll", other) }, LargeLandingCompensation: (words.Parameter1 & 255) != 0),
        EnemyDefinitionId.Boyon => new BoyonSpawnSettings(SpeedMultiplierIndex: Bits(words.Parameter1, 0, 8), JumpHeightIndex: Bits(words.Parameter1, 8, 8), TriggerDistance: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Bull => new BullSpawnSettings(IntervalsIndex: Bits(words.Parameter1, 0, 16), MaximumSpeedIndex: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Cacatac => new CacatacSpawnSettings(Direction: Bits(words.Parameter1, 0, 8) switch { 0 => CacatacDirection.Left, 1 => CacatacDirection.Right, 2 => CacatacDirection.InitialStop, var other => throw Unmapped("Direction", other) }, UpsideUp: (words.Parameter1 & 65280) != 0, DistanceIndex: Bits(words.Parameter2, 0, 8), SpeedIndex: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Choot => new ChootSpawnSettings(PatternIndex: Bits(words.Parameter1, 8, 8), PatternLoops: Bits(words.Parameter1, 0, 8), JumpDelay: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Chozo => new ChozoStatueSpawnSettings(Variant: Half(words.Parameter2)),
        EnemyDefinitionId.CorpseRipper or EnemyDefinitionId.CorpseSidehopper or EnemyDefinitionId.CorpseSkree or EnemyDefinitionId.CorpseZoomer => new CorpseSpawnSettings(Variant: Half(words.Parameter1)),
        EnemyDefinitionId.Sciser or EnemyDefinitionId.Zero or EnemyDefinitionId.Zeela or EnemyDefinitionId.Sova or EnemyDefinitionId.Zoomer or EnemyDefinitionId.MZoomer or EnemyDefinitionId.HZoomer or EnemyDefinitionId.Viola => new CrawlerSpawnSettings(Orientation: Bits(words.Initialization, 0, 2) switch { 0 => CrawlerSurfaceOrientation.UpsideRight, 1 => CrawlerSurfaceOrientation.UpsideLeft, 2 => CrawlerSurfaceOrientation.UpsideDown, 3 => CrawlerSurfaceOrientation.UpsideUp, var other => throw Unmapped("Orientation", other) }, BlockSide: Bits(words.SpeciesPropertyBits, 0, 2) switch { 0 => CrawlerSurfaceOrientation.UpsideRight, 1 => CrawlerSurfaceOrientation.UpsideLeft, 2 => CrawlerSurfaceOrientation.UpsideDown, 3 => CrawlerSurfaceOrientation.UpsideUp, var other => throw Unmapped("BlockSide", other) }, SpeedIndex: Bits(words.Parameter1, 0, 16), SurfaceTableOffset: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Multiviola => new MultiviolaSpawnSettings(Heading: Bits(words.Parameter1, 0, 16), Speed: Bits(words.Parameter2, 0, 8)),
        EnemyDefinitionId.Dragon => new DragonSpawnSettings(IsWing: (words.Parameter1 & 65535) != 0),
        EnemyDefinitionId.Elevator => new ElevatorSpawnSettings(DirectionIndex: Bits(words.Parameter1, 0, 16), ArrivalY: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Evir => new EvirSpawnSettings(IsArms: (words.Parameter1 & 65535) != 0, SpeedIndex: Bits(words.Parameter2, 0, 8), DirectionChangePeriod: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.FaceBlock => new FaceBlockSpawnSettings(TriggerDistance: Bits(words.Parameter1, 0, 16), Facing: Bits(words.Parameter2, 0, 1) switch { 0 => HorizontalDirection.Left, 1 => HorizontalDirection.Right, var other => throw Unmapped("Facing", other) }),
        EnemyDefinitionId.Fireflea => new FirefleaSpawnSettings(Circular: (words.Parameter1 & 2) != 0, PositiveSpeed: (words.Parameter1 & 1) != 0, InitialAngle: Bits(words.Parameter1, 8, 8), SpeedIndex: Bits(words.Parameter2, 0, 8), RadiusIndex: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Fune or EnemyDefinitionId.Namihe => new FuneNamiheSpawnSettings(Variant: Bits(words.Parameter1, 0, 4), FacesRight: (words.Parameter1 & 240) != 0, CooldownTime: Bits(words.Parameter1, 8, 8), LaunchIndex: Bits(words.Parameter2, 0, 8), YProximity: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.ShipBottomEntrance => new GunshipSpawnSettings(EntrancePad: (words.Parameter2 & 65535) != 0),
        EnemyDefinitionId.Hibashi => new HibashiSpawnSettings(InactiveTime: Bits(words.Parameter1, 0, 16), IsCollisionPart: (words.Parameter2 & 65535) != 0),
        EnemyDefinitionId.Sidehopper or EnemyDefinitionId.SidehopperLarge or EnemyDefinitionId.SidehopperTourian or EnemyDefinitionId.Dessgeega or EnemyDefinitionId.DessgeegaLarge => new HopperSpawnSettings(UpsideDown: (words.Parameter1 & 65535) != 0),
        EnemyDefinitionId.Kago => new KagoSpawnSettings(HitCount: Bits(words.Parameter1, 0, 16)),
        EnemyDefinitionId.KihunterGreen or EnemyDefinitionId.KihunterRed or EnemyDefinitionId.KihunterYellow => new KiHunterSpawnSettings(Wingless: (words.Parameter1 & 32768) != 0),
        EnemyDefinitionId.KihunterGreenWings or EnemyDefinitionId.KihunterRedWings or EnemyDefinitionId.KihunterYellowWings => new KiHunterWingsSpawnSettings(DetachHealth: Bits(words.Parameter1, 0, 16)),
        EnemyDefinitionId.KzanTop => new KzanSpawnSettings(FallSpeedIndex: Bits(words.Parameter1, 0, 8), FallWait: Bits(words.Parameter2, 0, 8), FallDistance: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Squeept or EnemyDefinitionId.Geruta or EnemyDefinitionId.Holtz => new EnemyFollowerSpawnSettings(FollowsParent: (words.Parameter1 & 32768) != 0),
        EnemyDefinitionId.Magdollite => new MagdolliteSpawnSettings(Part: Bits(words.Parameter1, 0, 16) switch { 0 => MagdollitePart.Head, 1 => MagdollitePart.RisingBody, 2 => MagdollitePart.TrackingOverlay, var other => throw Unmapped("Part", other) }, SpeedIndex: Bits(words.Parameter2, 8, 8), Range: Bits(words.Parameter2, 0, 8)),
        EnemyDefinitionId.MamaTurtle or EnemyDefinitionId.BabyTurtle => new TurtleSpawnSettings(Speed: Signed(words.Parameter1)),
        EnemyDefinitionId.Metroid => new MetroidSpawnSettings(IceDamageToFreeze: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Eye => new MorphBallEyeSpawnSettings(Facing: Bits(words.Parameter1, 0, 1) switch { 0 => HorizontalDirection.Right, 1 => HorizontalDirection.Left, var other => throw Unmapped("Facing", other) }, IsBeamMount: (words.Parameter2 & 32768) != 0, MountDirection: Bits(words.Parameter2, 0, 4)),
        EnemyDefinitionId.Puromi => new NuclearWaffleSpawnSettings(AngularSpeedIndex: Bits(words.Parameter1, 0, 8), OrbitRadius: Bits(words.Parameter1, 8, 8), Direction: Bits(words.Parameter2, 0, 8), WaitTime: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Owtch => new OwtchSpawnSettings(InitialState: Bits(words.Parameter1, 0, 8), UndergroundTimerIndex: Bits(words.Parameter1, 8, 8), SpeedIndex: Bits(words.Parameter2, 0, 8), DistanceIndex: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Zeb or EnemyDefinitionId.Zebbo => new BrinstarPipeBugSpawnSettings(Strong: (words.Parameter1 & 65535) != 0),
        EnemyDefinitionId.Gamet => new NorfairPipeBugSpawnSettings(TriggerWidth: Bits(words.Parameter2, 0, 8), SpeedIndex: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Geega => new YellowPipeBugSpawnSettings(Facing: Bits(words.Parameter1, 0, 16) switch { 0 => HorizontalDirection.Right, _ => HorizontalDirection.Left }, SpeedIndex: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Kamer2 or EnemyDefinitionId.Tripper => new PlatformSpawnSettings(Movement: Bits(words.Parameter1, 0, 16) switch { 0 => PlatformHorizontalMovement.Left, 1 => PlatformHorizontalMovement.Right, var other => throw Unmapped("Movement", other) }, SpeedIndex: Bits(words.Parameter2, 0, 8), MaximumYSpeedIndex: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Powamp => new PowampSpawnSettings(IsBalloon: (words.Parameter1 & 65535) != 0, GrappleTravelDistance: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Puyo => new PuyoSpawnSettings(HopCooldown: Bits(words.Parameter1, 0, 16), HopDistance: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Ripper or EnemyDefinitionId.Ripper2 => new RipperSpawnSettings(SpeedIndex: Bits(words.Parameter1, 0, 16), Direction: Bits(words.Parameter2, 0, 16) switch { 0 => HorizontalDirection.Left, _ => HorizontalDirection.Right }),
        EnemyDefinitionId.GRipper => new GRipperSpawnSettings(SpeedIndex: Bits(words.Initialization, 0, 8), Direction: Bits(words.Initialization, 0, 16) switch { 0 => GRipperStartDirection.Left, 256 => GRipperStartDirection.Left, _ => GRipperStartDirection.Right }, MinimumX: Bits(words.Parameter1, 0, 16), MaximumX: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Sbug => new SbugSpawnSettings(Speed: Bits(words.Parameter1, 0, 8), InitialAngle: Bits(words.Parameter1, 8, 8), ActivationRadius: Bits(words.Parameter2, 0, 8), Behavior: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.Shaktool => new ShaktoolSpawnSettings(Motion: (Has(words.Parameter1, 13) ? ShaktoolMotionFlags.ReversedOnce : ShaktoolMotionFlags.None) | (Has(words.Parameter1, 14) ? ShaktoolMotionFlags.Straightening : ShaktoolMotionFlags.None) | (Has(words.Parameter1, 15) ? ShaktoolMotionFlags.Clockwise : ShaktoolMotionFlags.None), Segment: Half(words.Parameter2)),
        EnemyDefinitionId.ShutterGrowing => new GrowingShutterSpawnSettings(Wait: Bits(words.Initialization, 0, 16) switch { 0 => GrowingShutterWait.Timer, 1 => GrowingShutterWait.SamusNear, var other => throw Unmapped("Wait", other) }, Growth: Bits(words.ExtraProperties, 0, 16) switch { 0 => GrowingShutterGrowth.Down, 1 => GrowingShutterGrowth.Up, var other => throw Unmapped("Growth", other) }, ActivationDistance: Bits(words.Parameter1, 0, 16), GrowthSpeedIndex: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.ShutterShootable or EnemyDefinitionId.ShutterDestroyable or EnemyDefinitionId.Kamer or EnemyDefinitionId.ShutterHorizShootable => new ShutterSpawnSettings(SpeedIndex: Bits(words.Initialization, 0, 8), PrimaryDirection: Bits(words.Initialization, 8, 8) switch { 0 => ShutterHeading.LeftOrUp, 1 => ShutterHeading.RightOrDown, var other => throw Unmapped("PrimaryDirection", other) }, TriggerMode: Bits(words.Parameter1, 0, 8) switch { 0 => ShutterTriggerMode.Timer, 1 => ShutterTriggerMode.HorizontalProximity, 2 => ShutterTriggerMode.Immediate, 3 => ShutterTriggerMode.OneShotReaction, 4 => ShutterTriggerMode.RepeatableReaction, var other => throw Unmapped("TriggerMode", other) }, TravelDistance: Bits(words.Parameter1, 8, 8), ProximityOrWaitTime: Bits(words.Parameter2, 0, 16), FirstRestUnits: Bits(words.ExtraProperties, 0, 8), SecondRestUnits: Bits(words.ExtraProperties, 8, 8)),
        EnemyDefinitionId.Skultera => new SkulteraSpawnSettings(SpeedIndex: Bits(words.Parameter1, 0, 8), StartsLeft: (words.Parameter1 & 65280) != 0, Radius: Bits(words.Parameter2, 0, 8), AngleDelta: Bits(words.Parameter2, 8, 8)),
        EnemyDefinitionId.PirateGoldWalking or EnemyDefinitionId.PirateGreenWalking or EnemyDefinitionId.PirateGreyWalking or EnemyDefinitionId.PirateMagentaWalking or EnemyDefinitionId.PirateRedWalking or EnemyDefinitionId.PirateSilverWalking => new WalkingSpacePirateSpawnSettings(Options: (Has(words.Parameter1, 0) ? WalkingSpacePirateParameterFlags.StartsFacingRight : WalkingSpacePirateParameterFlags.None) | (Has(words.Parameter1, 15) ? WalkingSpacePirateParameterFlags.SlowLaserAndProjectileFlinch : WalkingSpacePirateParameterFlags.None), PatrolReach: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.PirateGoldWall or EnemyDefinitionId.PirateGreenWall or EnemyDefinitionId.PirateGreyWall or EnemyDefinitionId.PirateMagentaWall or EnemyDefinitionId.PirateRedWall or EnemyDefinitionId.PirateSilverWall => new WallSpacePirateSpawnSettings(Options: (Has(words.Parameter1, 0) ? WallSpacePirateParameterFlags.StartsOnRightWall : WallSpacePirateParameterFlags.None) | (Has(words.Parameter1, 15) ? WallSpacePirateParameterFlags.SlowJumpAndLaser : WallSpacePirateParameterFlags.None), JumpSpan: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.PirateGoldNinja or EnemyDefinitionId.PirateGreenNinja or EnemyDefinitionId.PirateGreyNinja or EnemyDefinitionId.PirateMagentaNinja or EnemyDefinitionId.PirateRedNinja or EnemyDefinitionId.PirateSilverNinja => new NinjaSpacePirateSpawnSettings(Options: (Has(words.Parameter1, 0) ? NinjaSpacePirateParameterFlags.StartsAtLeftPostFacingRight : NinjaSpacePirateParameterFlags.None), PostDistance: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Spark => new SparkSpawnSettings(InitialState: Bits(words.Parameter1, 0, 16), BaseFunctionTime: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Stoke => new StokeSpawnSettings(Direction: Bits(words.Parameter1, 0, 16) switch { 0 => StokeDirection.Left, 1 => StokeDirection.Right, var other => throw Unmapped("Direction", other) }, SpeedIndex: Bits(words.Parameter2, 0, 16)),
        EnemyDefinitionId.Waver => new WaverSpawnSettings(Facing: Bits(words.Parameter1, 0, 1) switch { 0 => HorizontalDirection.Left, 1 => HorizontalDirection.Right, var other => throw Unmapped("Facing", other) }),
        EnemyDefinitionId.Robot or EnemyDefinitionId.RobotNoPower => new WorkRobotSpawnSettings(Pose: Bits(words.Parameter1, 0, 16)),
        EnemyDefinitionId.YappingMaw => new YappingMawSpawnSettings(ActivationDistance: Bits(words.Parameter1, 0, 16), Attack: Bits(words.Parameter2, 0, 16) switch { 0 => VerticalDirection.Down, _ => VerticalDirection.Up }),
        EnemyDefinitionId.Yard => new YardSpawnSettings(Direction: Bits(words.Initialization, 0, 16) switch { 0 => YardDirection.UpsideRightMovingUp, 1 => YardDirection.UpsideRightMovingDown, 2 => YardDirection.UpsideLeftMovingUp, 3 => YardDirection.UpsideLeftMovingDown, 4 => YardDirection.UpsideDownMovingLeft, 5 => YardDirection.UpsideDownMovingRight, 6 => YardDirection.UpsideUpMovingLeft, 7 => YardDirection.UpsideUpMovingRight, var other => throw Unmapped("Direction", other) }, SpeedIndex: Bits(words.Parameter1, 0, 16)),
        _ => EnemySpawnSettings.None,
    };

    /// <summary>Whether the species reads its settings from the extra-property word, which then holds no additional property.</summary>
    public static bool TakesExtraPropertySettings(EnemyDefinitionId enemy) => enemy is EnemyDefinitionId.ShutterGrowing or EnemyDefinitionId.ShutterShootable or EnemyDefinitionId.ShutterDestroyable or EnemyDefinitionId.Kamer or EnemyDefinitionId.ShutterHorizShootable;

    /// <summary>The words that decode to <paramref name="settings"/> for its species; a species told nothing gets zero words.</summary>
    /// <exception cref="ArgumentException">No words decode to the settings.</exception>
    public static PopulationWords Encode(EnemySpawnSettings settings) => Ensure.NotNull(settings) switch
    {
        CeresDoorSpawnSettings s => Checked(EnemyDefinitionId.CeresDoor, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Variant switch { CeresDoorVariant.NormalFacingRight => 0, CeresDoorVariant.NormalFacingLeft => 1, CeresDoorVariant.RotatingElevatorPreExplosionOverlay => 2, CeresDoorVariant.RidleyRoomFacingRight => 3, CeresDoorVariant.RotatingElevatorInvisibleWall => 4, CeresDoorVariant.RidleyEscapeFloorLeftWall => 5, CeresDoorVariant.RidleyEscapeFloorRightWall => 6, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 0), Parameter2: 0)),
        CeresSteamSpawnSettings s => Checked(EnemyDefinitionId.Steam, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Variant switch { CeresSteamVariant.Up => 0, CeresSteamVariant.Left => 1, CeresSteamVariant.Down => 2, CeresSteamVariant.Right => 3, CeresSteamVariant.RotatingElevatorLeft => 4, CeresSteamVariant.RotatingElevatorRight => 5, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 0), Parameter2: 0)),
        TourianEntranceStatueSpawnSettings s => Checked(EnemyDefinitionId.TourianStatue, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Statue switch { TourianEntranceStatueProgram.BaseDecoration => 0, TourianEntranceStatueProgram.Ridley => 2, TourianEntranceStatueProgram.Phantoon => 4, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 0), Parameter2: 0)),
        MotherBrainTubeSpawnSettings s => Checked(EnemyDefinitionId.MotherBrainTubes, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Piece switch { MotherBrainTubePiece.BottomLeft => 0, MotherBrainTubePiece.BottomRight => 1, MotherBrainTubePiece.BottomMiddleLeft => 2, MotherBrainTubePiece.BottomMiddleRight => 3, MotherBrainTubePiece.Main => 4, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 1), Parameter2: Place(s.FallDelay, 0, 16))),
        RinkaSpawnSettings s => Checked(EnemyDefinitionId.Rinka, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: (s.Special ? 1 : 0), Parameter2: 0)),
        ZebetiteSpawnSettings s => Checked(EnemyDefinitionId.Zebetite, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Half switch { ZebetiteHalf.Primary => 0, ZebetiteHalf.Linked => 2, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 0), Parameter2: 0)),
        RidleyExplosionSpawnSettings s => Checked(EnemyDefinitionId.RidleyExplosion, settings, new PopulationWords(Initialization: 0, SpeciesPropertyBits: 0, ExtraProperties: 0, Parameter1: ((s.Part switch { RidleyExplosionPart.Tail0 => 0, RidleyExplosionPart.Tail1 => 2, RidleyExplosionPart.Tail2 => 4, RidleyExplosionPart.Tail3 => 6, RidleyExplosionPart.Tail4 => 8, RidleyExplosionPart.Tail5 => 10, RidleyExplosionPart.TailTip => 12, RidleyExplosionPart.Wings => 14, RidleyExplosionPart.Legs => 16, RidleyExplosionPart.OpenHeadAndNeck => 18, RidleyExplosionPart.Torso => 20, RidleyExplosionPart.Claw => 22, _ => throw new ArgumentOutOfRangeException(nameof(settings)) }) << 0), Parameter2: 0)),
